public class OutboxWorker(IServiceScopeFactory scopes, ILogger<OutboxWorker> log)
    : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        while (await timer.WaitForNextTickAsync(stoppingToken))
        {
            await using var scope = scopes.CreateAsyncScope();     // nowy scope
            var db = scope.ServiceProvider.GetRequiredService<AppDb>();
            var pending = await db.Outbox.Where(m => !m.Sent).Take(50)
                                  .ToListAsync(stoppingToken);
            log.LogInformation("Processing {Count} messages", pending.Count);
            // ... wysyłka, oznaczenie Sent = true, SaveChangesAsync
        }
    }
}

