app.MapGet("/api/v1/products", async (AppDb db, int page = 1, int pageSize = 20,
                                       CancellationToken ct = default) =>
{
    pageSize = Math.Clamp(pageSize, 1, 100);           // limit rozmiaru strony
    var query = db.Products.AsNoTracking().OrderBy(p => p.Id); // stabilne sortowanie
    var total = await query.CountAsync(ct);
    var items = await query.Skip((page - 1) * pageSize).Take(pageSize)
        .Select(p => new ProductDto(p.Id, p.Name, p.Price))   // projekcja do DTO
        .ToListAsync(ct);
    return TypedResults.Ok(new PagedResult<ProductDto>(items, page, pageSize, total));
});

